#include <iostream>
#include <string>
#include <sstream>

int main() {
    int w, m;
    std::cin >> w >> m;
    int flag = 0;
    for (int i = 1; i <= 100; ++i) {
        if (m % w == 0)
            m /= w;
        else if ((m + 1) % w == 0)
            m = (m + 1) / w;
        else if ((m - 1) % w == 0)
            m = (m - 1) / w;
        else {
            flag = 1;
            break;
        }
        if (m == 0)
            break;
        if (i == 100 && !(m == 1 || m == 0))
            flag = 1;
    }
    if (flag == 1)
        std::cout << "NO" << std::endl;
    else
        std::cout << "YES" << std::endl;
    return 0;
}

